use kujo::interpreter::Value;
use std::sync::Arc;
use std::alloc::{GlobalAlloc, Layout, System};
use std::cell::Cell;
thread_local! {
    static TRACK: Cell<bool> = const { Cell::new(false) };
    static COUNT: Cell<usize> = const { Cell::new(0) };
}
struct Counting;
unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        if TRACK.with(Cell::get) { COUNT.with(|n| n.set(n.get()+1)); }
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, p: *mut u8, layout: Layout) { unsafe { System.dealloc(p, layout) } }
}
#[global_allocator] static ALLOCATOR: Counting = Counting;
fn main() {
    let array = Value::array(vec![Value::Int(7)]);
    let bytes = Value::Bytes(Arc::new(vec![0,255]));
    let dict = Value::Dict(Arc::new(Default::default()));
    let structure = |name: &str, child: Value, scalar: f64| Value::Struct {
        name: name.into(), fields: Arc::new([("child".into(),child),("scalar".into(),Value::Float(scalar))].into_iter().collect())
    };
    let mut cases = vec![array.clone(),array.clone(),Value::array(vec![Value::Int(7)]),bytes.clone(),bytes.clone(),Value::Bytes(Arc::new(vec![0,255])),dict.clone(),dict,Value::Dict(Arc::new(Default::default())),Value::Int(7),Value::Float(0.0),Value::Bool(true),Value::Null,Value::Str(Arc::new("s".into())),Value::IntDict(Arc::new(Default::default()))];
    let a = structure("State",array.clone(),0.0);
    cases.extend([a.clone(),a,structure("State",array.clone(),0.0),structure("State",array.clone(),-0.0),structure("Other",array.clone(),0.0),structure("State",Value::array(vec![Value::Int(7)]),0.0)]);
    let mut deep = array;
    for _ in 0..128 { deep = structure("Node",deep,0.0); }
    cases.extend([deep.clone(),deep]);
    for (i,a) in cases.iter().enumerate() {
        for (j,b) in cases.iter().enumerate() {
            assert_eq!(same_storage_before(a,b),same_storage_after(a,b),"pair {i},{j}");
        }
    }
    for (label, f) in [("before",same_storage_before as fn(&Value,&Value)->bool),("after",same_storage_after)] {
        COUNT.with(|n|n.set(0)); TRACK.with(|v|v.set(true));
        for _ in 0..10000 {
            assert!(f(&cases[0],&cases[1]));
            assert!(!f(&cases[0],&cases[2]));
            assert!(f(&cases[3],&cases[4]));
            assert!(f(&cases[6],&cases[7]));
        }
        TRACK.with(|v|v.set(false));
        let count=COUNT.with(Cell::get);
        println!("{label}: calls=40000 allocations={count}");
        assert_eq!(count,if label=="before"{40000}else{0});
    }
    println!("PASS {} semantic pairs",cases.len()*cases.len());
}
fn same_storage_before(a: &Value, b: &Value) -> bool {
    // Scalars alone do not benefit from release. Struct field maps are owned,
    // but their storage-backed children can be released without walking payloads.
    if !matches!(a, Value::Array(_) | Value::Bytes(_) | Value::Dict(_) | Value::Struct { .. }) {
        return false;
    }
    let mut pending = vec![(a, b)];
    while let Some((a, b)) = pending.pop() {
        let same = match (a, b) {
            (Value::Array(a), Value::Array(b)) => Arc::ptr_eq(a, b),
            (Value::Bytes(a), Value::Bytes(b)) => Arc::ptr_eq(a, b),
            (Value::Dict(a), Value::Dict(b)) => Arc::ptr_eq(a, b),
            (Value::Str(a), Value::Str(b)) => Arc::ptr_eq(a, b),
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a.to_bits() == b.to_bits(),
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Null, Value::Null) => true,
            (
                Value::Struct { name: a_name, fields: a },
                Value::Struct { name: b_name, fields: b },
            ) if a_name == b_name && a.len() == b.len() => {
                if Arc::ptr_eq(a, b) {
                    continue;
                }
                for (key, value) in a.iter() {
                    let Some(other) = b.get(key) else { return false };
                    pending.push((value, other));
                }
                true
            }
            _ => false,
        };
        if !same {
            return false;
        }
    }
    true
}
fn same_storage_after(a: &Value, b: &Value) -> bool {
    // Scalars alone do not benefit from release. Struct field maps are owned,
    // but their storage-backed children can be released without walking payloads.
    match (a,b) {
        (Value::Array(a),Value::Array(b)) => return Arc::ptr_eq(a,b),
        (Value::Bytes(a),Value::Bytes(b)) => return Arc::ptr_eq(a,b),
        (Value::Dict(a),Value::Dict(b)) => return Arc::ptr_eq(a,b),
        (Value::Struct { .. },Value::Struct { .. }) => {},
        _ => return false,
    }
    let mut pending = vec![(a, b)];
    while let Some((a, b)) = pending.pop() {
        let same = match (a, b) {
            (Value::Array(a), Value::Array(b)) => Arc::ptr_eq(a, b),
            (Value::Bytes(a), Value::Bytes(b)) => Arc::ptr_eq(a, b),
            (Value::Dict(a), Value::Dict(b)) => Arc::ptr_eq(a, b),
            (Value::Str(a), Value::Str(b)) => Arc::ptr_eq(a, b),
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a.to_bits() == b.to_bits(),
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Null, Value::Null) => true,
            (
                Value::Struct { name: a_name, fields: a },
                Value::Struct { name: b_name, fields: b },
            ) if a_name == b_name && a.len() == b.len() => {
                if Arc::ptr_eq(a, b) {
                    continue;
                }
                for (key, value) in a.iter() {
                    let Some(other) = b.get(key) else { return false };
                    pending.push((value, other));
                }
                true
            }
            _ => false,
        };
        if !same {
            return false;
        }
    }
    true
}
